/**
 * This writes stdout and stderr to the FileProcessResult.
 *
 * @param pb
 * @param timeoutMillis
 * @param maxStdoutBuffer
 * @param maxStdErrBuffer
 * @return
 * @throws IOException
 */
public static FileProcessResult execute(ProcessBuilder pb, long timeoutMillis, int maxStdoutBuffer, int maxStdErrBuffer) throws IOException {
    Process p = null;
    String id = null;
    try {
        p = pb.start();
        id = register(p);
        long elapsed = -1;
        long start = System.currentTimeMillis();
